describe('Bulk Delete List Items', () => {
  beforeEach(() => {
    cy.visit('/list-items');
  });

  it('should successfully bulk-delete selected items from a list', () => {
    // Verify initial list is displayed
    cy.get('[data-testid="item-list"]').should('be.visible');
    cy.get('[data-testid="item-list"]').should('contain', 'Item 1');
    cy.get('[data-testid="item-list"]').should('contain', 'Item 2');
    cy.get('[data-testid="item-list"]').should('contain', 'Item 3');

    // Select multiple items by clicking checkboxes
    cy.get('[data-testid="item-checkbox-1"]').click();
    cy.get('[data-testid="item-checkbox-2"]').click();
    cy.get('[data-testid="item-checkbox-3"]').click();

    // Verify selection is highlighted
    cy.get('[data-testid="item-checkbox-1"]').should('be.checked');
    cy.get('[data-testid="item-checkbox-2"]').should('be.checked');
    cy.get('[data-testid="item-checkbox-3"]').should('be.checked');

    // Click bulk delete button
    cy.get('[data-testid="bulk-delete-btn"]').click();

    // Verify confirmation modal appears
    cy.get('[data-testid="confirm-delete-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-delete-modal"]').should('contain', 'Are you sure you want to delete?');

    // Click confirm button
    cy.get('[data-testid="confirm-delete-btn"]').click();

    // Verify items are removed from the list
    cy.get('[data-testid="item-list"]').should('not.contain', 'Item 1');
    cy.get('[data-testid="item-list"]').should('not.contain', 'Item 2');
    cy.get('[data-testid="item-list"]').should('not.contain', 'Item 3');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Items deleted successfully');

    // Verify list is now empty
    cy.get('[data-testid="item-list"]').should('be.empty');
  });

  it('should handle bulk delete with no selected items', () => {
    // Verify initial list is displayed
    cy.get('[data-testid="item-list"]').should('be.visible');
    cy.get('[data-testid="item-list"]').should('contain', 'Item 1');
    cy.get('[data-testid="item-list"]').should('contain', 'Item 2');

    // Click bulk delete button
    cy.get('[data-testid="bulk-delete-btn"]').click();

    // Verify confirmation modal appears
    cy.get('[data-testid="confirm-delete-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-delete-modal"]').should('contain', 'No items selected');

    // Click cancel button
    cy.get('[data-testid="cancel-delete-btn"]').click();

    // Verify list remains unchanged
    cy.get('[data-testid="item-list"]').should('contain', 'Item 1');
    cy.get('[data-testid="item-list"]').should('contain', 'Item 2');

    // Verify success message is not displayed
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});
